class Inventory:
    def __init__(self):
        self._stock = {}

    def y_add_stock(self, item, quantity):
        """
        Adds a specified quantity of an item to the inventory.
        """
        if item in self._stock:
            self._stock[item] += quantity
        else:
            self._stock[item] = quantity

    def y_remove_stock(self, item, quantity):
        """
        Removes a specified quantity of an item from the inventory.
        """
        if item in self._stock:
            if self._stock[item] >= quantity:
                self._stock[item] -= quantity
                if self._stock[item] == 0:
                    del self._stock[item]
            else:
                raise ValueError(f"Insufficient stock for {item}.")
        else:
            raise ValueError(f"{item} not found in inventory.")
