        self.md__init__ = None

    def y_merge_sort(self, y_list):
        y_y = len(y_list)
        if y_y <= 1:
            return y_list
        y_mid = y_y // 2
        y_left = self.y_merge_sort(y_list[:y_mid])
        y_right = self.y_merge_sort(y_list[y_mid:])
        return self.md_merge(y_left, y_right)

    def md_merge(self, y_left, y_right):
        y_result = []
        y_i = y_j = 0
        while y_i < len(y_left) and y_j < len(y_right):
            if y_left[y_i] < y_right[y_j]:
                y_result.append(y_left[y_i])
                y_i += 1
            else:
                y_result.append(y_right[y_j])
                y_j += 1
        y_result.extend(y_left[y_i:])
        y_result.extend(y_right[y_j:])
        return y_result
